const lessons = [{"id": 1, "title": "Swadharma: living your own authentic calling", "topic": "Hindu Philosophy & Classical Strategy", "summary": "Better is one's own duty, though imperfectly performed, than the duty of another well performed. Striving in another's nature brings profound peril.", "url": "lessons/001-swadharma-vs-paradharma.html", "deepWords": 2510, "deepMins": 13}, {"id": 2, "title": "Why the Roman Empire transformed and fragmented", "topic": "Institutions, History & Anthropology", "summary": "The western Roman Empire did not fall for one simple reason. Political instability, fiscal pressures, military change, external groups and regional differences interacted over time.", "url": "lessons/002-why-the-roman-empire-transformed-and-fragmented.html", "deepWords": 1995, "deepMins": 10}, {"id": 3, "title": "Media literacy: follow the source", "topic": "Technology, AI & Media Ecology", "summary": "A claim can change as it travels through headlines, commentary and social media. Source tracing helps distinguish original evidence from repetition.", "url": "lessons/003-media-literacy-follow-the-source.html", "deepWords": 2156, "deepMins": 11}, {"id": 4, "title": "The role of state capacity", "topic": "Institutions, History & Anthropology", "summary": "A state needs the practical ability to collect revenue, implement decisions, provide public goods and enforce law. Announcements without delivery reveal a gap between formal authority and capacity.", "url": "lessons/004-the-role-of-state-capacity.html", "deepWords": 2078, "deepMins": 10}, {"id": 5, "title": "Artificial intelligence: capability, limits and accountability", "topic": "Technology, AI & Media Ecology", "summary": "AI systems can recognise patterns and generate useful outputs, but their reliability depends on data, evaluation, context and oversight. Fluency is not the same as truth or understanding.", "url": "lessons/005-artificial-intelligence-capability-limits-and-accountability.html", "deepWords": 2747, "deepMins": 14}, {"id": 6, "title": "Abhyasa and Vairagya: the twin wings of mastery", "topic": "Hindu Philosophy & Classical Strategy", "summary": "The restless, wandering mind is mastered through two complementary disciplines: relentless, sustained practice (abhyasa) and radical emotional dispassion (vairagya).", "url": "lessons/006-abhyasa-and-vairagya-practice-and-dispassion.html", "deepWords": 2239, "deepMins": 11}, {"id": 7, "title": "The difference between a model and reality", "topic": "Scientific Reasoning & Epistemology", "summary": "Models simplify reality to help explain or predict selected features. A useful model is not a complete picture; its assumptions define where it may fail.", "url": "lessons/007-the-difference-between-a-model-and-reality.html", "deepWords": 2332, "deepMins": 12}, {"id": 8, "title": "Inflation: why rising prices matter differently to different people", "topic": "Economics, Markets & Incentives", "summary": "Inflation is a sustained rise in the general price level. Its effects vary because households buy different baskets of goods and have different incomes, savings and debts.", "url": "lessons/008-inflation-why-rising-prices-matter-differently-to-different-people.html", "deepWords": 2223, "deepMins": 11}, {"id": 9, "title": "The difference between empathy and agreement", "topic": "Philosophy, Ethics & Mind", "summary": "Empathy is the effort to understand another person&#39;s experience. It does not require endorsing their interpretation or accepting harmful conduct.", "url": "lessons/009-the-difference-between-empathy-and-agreement.html", "deepWords": 2400, "deepMins": 12}, {"id": 10, "title": "The intersubjective reality", "topic": "Institutions, History & Anthropology", "summary": "Human cooperation at scale relies on intersubjective realities—shared fictions like money, corporations, and laws that exist only in our collective imagination.", "url": "lessons/010-the-intersubjective-reality.html", "deepWords": 2519, "deepMins": 13}, {"id": 11, "title": "The power and limits of narratives", "topic": "Technology, AI & Media Ecology", "summary": "Stories organise facts into causes, characters and consequences. They make complex events memorable, but can hide uncertainty and make coincidence look inevitable.", "url": "lessons/011-the-power-and-limits-of-narratives.html", "deepWords": 2276, "deepMins": 11}, {"id": 12, "title": "Why humans make art", "topic": "Philosophy, Ethics & Mind", "summary": "Art can express emotion, preserve memory, challenge norms, create shared identity or invite attention to form. It need not justify itself through practical utility.", "url": "lessons/012-why-humans-make-art.html", "deepWords": 2097, "deepMins": 10}, {"id": 13, "title": "Pu: the power of the uncarved block", "topic": "Hindu Philosophy & Classical Strategy", "summary": "In simplicity and raw, unconditioned openness lies infinite potential. Returning to the original state shields against artificial dogma.", "url": "lessons/013-pu-the-uncarved-block.html", "deepWords": 2266, "deepMins": 11}, {"id": 14, "title": "Second-order thinking", "topic": "Decision Science & Cognitive Biases", "summary": "First-order thinking asks what happens immediately. Second-order thinking asks what happens next, how others respond and what those responses cause.", "url": "lessons/014-second-order-thinking.html", "deepWords": 2281, "deepMins": 11}, {"id": 15, "title": "Why status matters", "topic": "Institutions, History & Anthropology", "summary": "Status influences attention, access, credibility and group behaviour. It can be earned through competence, generosity, courage, wealth, lineage or control of scarce resources.", "url": "lessons/015-why-status-matters.html", "deepWords": 1961, "deepMins": 10}, {"id": 16, "title": "The hidden curriculum of workplaces", "topic": "Systems Thinking & Complexity", "summary": "People learn workplace norms from what leaders reward, tolerate and model—not only from formal values statements.", "url": "lessons/016-the-hidden-curriculum-of-workplaces.html", "deepWords": 2074, "deepMins": 10}, {"id": 17, "title": "The hard problem of consciousness", "topic": "Philosophy, Ethics & Mind", "summary": "The hard problem asks why and how physical processes are accompanied by subjective experience. It is a live philosophical debate, not a settled proof for or against any metaphysical position.", "url": "lessons/017-the-hard-problem-of-consciousness.html", "deepWords": 2018, "deepMins": 10}, {"id": 18, "title": "The power of asking better questions", "topic": "Scientific Reasoning & Epistemology", "summary": "A good question exposes assumptions, clarifies definitions or identifies missing evidence. It can improve a discussion more than a quick answer.", "url": "lessons/018-the-power-of-asking-better-questions.html", "deepWords": 2095, "deepMins": 10}, {"id": 19, "title": "Why sleep, movement and environment affect judgment", "topic": "Social Psychology & Human Nature", "summary": "Cognitive performance is shaped by basic conditions such as sleep, stress, movement and the environment. Good reasoning is harder when attention and energy are depleted.", "url": "lessons/019-why-sleep-movement-and-environment-affect-judgment.html", "deepWords": 2496, "deepMins": 12}, {"id": 20, "title": "What makes an institution strong?", "topic": "Institutions, History & Anthropology", "summary": "Institutions are the formal and informal rules that shape behaviour. Their quality depends on legitimacy, capacity, accountability and how rules are enforced.", "url": "lessons/020-what-makes-an-institution-strong.html", "deepWords": 2108, "deepMins": 11}, {"id": 21, "title": "The beginner&#39;s mind", "topic": "Scientific Reasoning & Epistemology", "summary": "A beginner&#39;s mind is a willingness to encounter familiar subjects without assuming that prior knowledge has settled every question. It makes room for observation and revision.", "url": "lessons/021-the-beginner-s-mind.html", "deepWords": 2583, "deepMins": 13}, {"id": 22, "title": "The planning fallacy", "topic": "Decision Science & Cognitive Biases", "summary": "People often underestimate the time, cost and difficulty of their own plans, even when similar projects have run late before.", "url": "lessons/022-the-planning-fallacy.html", "deepWords": 2350, "deepMins": 12}, {"id": 23, "title": "Why compound growth is powerful", "topic": "Economics, Markets & Incentives", "summary": "Compounding occurs when gains or interest are added to a base and future growth applies to the enlarged amount. It works in learning and relationships as well as finance.", "url": "lessons/023-why-compound-growth-is-powerful.html", "deepWords": 2330, "deepMins": 12}, {"id": 24, "title": "Correlation is not causation", "topic": "Scientific Reasoning & Epistemology", "summary": "Two things moving together does not establish that one caused the other. A third factor, reverse causation or coincidence may explain the pattern.", "url": "lessons/024-correlation-is-not-causation.html", "deepWords": 2563, "deepMins": 13}, {"id": 25, "title": "Buddhist impermanence and attachment", "topic": "Hindu Philosophy & Classical Strategy", "summary": "Buddhist teachings on impermanence examine how changing conditions affect experience. Attachment to permanence can intensify distress when people, roles and circumstances change.", "url": "lessons/025-buddhist-impermanence-and-attachment.html", "deepWords": 2524, "deepMins": 13}, {"id": 26, "title": "Why reputation is a long-term asset", "topic": "Game Theory & Cooperation", "summary": "Reputation summarises how others expect you to behave. It can reduce the need for costly verification, but it is fragile when claims and conduct diverge.", "url": "lessons/026-why-reputation-is-a-long-term-asset.html", "deepWords": 2474, "deepMins": 12}, {"id": 27, "title": "Music, emotion and memory", "topic": "Philosophy, Ethics & Mind", "summary": "Music engages systems involved in prediction, movement, emotion and memory. Personal associations and cultural learning also shape what a piece means to a listener.", "url": "lessons/027-music-emotion-and-memory.html", "deepWords": 2193, "deepMins": 11}, {"id": 28, "title": "The luxury trap: why technological ease creates new burdens", "topic": "Institutions, History & Anthropology", "summary": "Improvements in aggregate productivity often increase individual daily toil rather than leisure. Luxuries tend to become necessities and spawn new obligations.", "url": "lessons/028-the-luxury-trap-the-agricultural-con.html", "deepWords": 2473, "deepMins": 12}, {"id": 29, "title": "Identity: why belonging can override evidence", "topic": "Social Psychology & Human Nature", "summary": "Group identity can shape what people notice, trust and defend. Criticism of an idea may be experienced as criticism of the group itself.", "url": "lessons/029-identity-why-belonging-can-override-evidence.html", "deepWords": 3598, "deepMins": 18}, {"id": 30, "title": "Nyaya: knowledge needs reliable means", "topic": "Hindu Philosophy & Classical Strategy", "summary": "The Nyaya tradition analyses valid knowledge and discusses perception, inference, comparison and testimony. It offers a rigorous vocabulary for examining how claims are justified.", "url": "lessons/030-nyaya-knowledge-needs-reliable-means.html", "deepWords": 2177, "deepMins": 11}, {"id": 31, "title": "The scientific revolution: admitting ignorance", "topic": "Scientific Reasoning & Epistemology", "summary": "Modern science began not with the discovery of great truths, but with the radical, humble willingness to say: 'We do not know.'", "url": "lessons/031-the-scientific-creed-of-ignorance.html", "deepWords": 2565, "deepMins": 13}, {"id": 32, "title": "How to think in probabilities", "topic": "Decision Science & Cognitive Biases", "summary": "Many real-world judgments are uncertain rather than simply true or false. Probability helps express degrees of confidence and update beliefs as evidence changes.", "url": "lessons/032-how-to-think-in-probabilities.html", "deepWords": 2946, "deepMins": 15}, {"id": 33, "title": "The value of changing your mind", "topic": "Scientific Reasoning & Epistemology", "summary": "Changing a belief in response to better evidence is a sign of learning, not weakness. Consistency is valuable only when the reasons remain sound.", "url": "lessons/033-the-value-of-changing-your-mind.html", "deepWords": 2118, "deepMins": 11}, {"id": 34, "title": "How framing changes decisions", "topic": "Decision Science & Cognitive Biases", "summary": "The same options can feel different when described as gains, losses, risks or opportunities. Framing changes attention even when underlying facts remain constant.", "url": "lessons/034-how-framing-changes-decisions.html", "deepWords": 2135, "deepMins": 11}, {"id": 35, "title": "Learning how to learn", "topic": "Scientific Reasoning & Epistemology", "summary": "Learning improves when people retrieve ideas from memory, space practice over time, connect new concepts to prior knowledge and receive useful feedback.", "url": "lessons/035-learning-how-to-learn.html", "deepWords": 2555, "deepMins": 13}, {"id": 36, "title": "Stoicism: focus on what is within your control", "topic": "Philosophy, Ethics & Mind", "summary": "Stoic practice distinguishes what depends on us—such as our judgments and actions—from what does not fully depend on us, such as reputation or other people&#39;s choices.", "url": "lessons/036-stoicism-focus-on-what-is-within-your-control.html", "deepWords": 2466, "deepMins": 12}, {"id": 37, "title": "The base-rate habit", "topic": "Decision Science & Cognitive Biases", "summary": "A vivid individual story can distract from how common an outcome is in the relevant population. Base rates provide essential context.", "url": "lessons/037-the-base-rate-habit.html", "deepWords": 2059, "deepMins": 10}, {"id": 38, "title": "Rituals: why repeated actions matter", "topic": "Institutions, History & Anthropology", "summary": "Rituals can create belonging, mark transitions, transmit values and coordinate groups. Their meaning may be social, emotional, religious or political.", "url": "lessons/038-rituals-why-repeated-actions-matter.html", "deepWords": 2821, "deepMins": 14}, {"id": 39, "title": "Anchoring: the first number sticks", "topic": "Decision Science & Cognitive Biases", "summary": "An initial number or reference point can influence later estimates, even when it is arbitrary or only weakly relevant.", "url": "lessons/039-anchoring-the-first-number-sticks.html", "deepWords": 2164, "deepMins": 11}, {"id": 40, "title": "The inner battlefield: awareness versus the field of habit", "topic": "Hindu Philosophy & Classical Strategy", "summary": "The true Kurukshetra is not an ancient geographical plain; it is the human psyche, where the silent witness of awareness observes the field of conditioned impulses.", "url": "lessons/040-the-inner-battlefield-kshetra-kshetrajna.html", "deepWords": 2336, "deepMins": 12}, {"id": 41, "title": "The scientific method as a way of living", "topic": "Scientific Reasoning & Epistemology", "summary": "Science is a disciplined process of forming testable explanations, gathering evidence, exposing claims to criticism and revising conclusions. It is not a guarantee that every scientist is unbiased.", "url": "lessons/041-the-scientific-method-as-a-way-of-living.html", "deepWords": 2223, "deepMins": 11}, {"id": 42, "title": "The network effect", "topic": "Economics, Markets & Incentives", "summary": "Some services become more useful as more people use them. This can create rapid growth and concentration, but network size alone does not guarantee trust or quality.", "url": "lessons/042-the-network-effect.html", "deepWords": 2121, "deepMins": 11}, {"id": 43, "title": "The bystander effect and shared responsibility", "topic": "Social Psychology & Human Nature", "summary": "In some emergencies, the presence of other witnesses can diffuse responsibility. People may look to others for cues about whether action is needed.", "url": "lessons/043-the-bystander-effect-and-shared-responsibility.html", "deepWords": 2167, "deepMins": 11}, {"id": 44, "title": "Why some countries become wealthy", "topic": "Economics, Markets & Incentives", "summary": "Long-run prosperity is associated with interacting factors such as institutions, human capital, technology, geography, trade and state capacity. No single explanation fits every country.", "url": "lessons/044-why-some-countries-become-wealthy.html", "deepWords": 2008, "deepMins": 10}, {"id": 45, "title": "The difference between cynicism and realism", "topic": "Social Psychology & Human Nature", "summary": "Realism attends to evidence, incentives and constraints. Cynicism assumes bad motives too readily and can miss genuine generosity, competence and cooperation.", "url": "lessons/045-the-difference-between-cynicism-and-realism.html", "deepWords": 2509, "deepMins": 13}, {"id": 46, "title": "The veil of ignorance", "topic": "Philosophy, Ethics & Mind", "summary": "John Rawls asks us to imagine choosing principles for society without knowing our future position in it. The thought experiment tests whether rules are fair beyond self-interest.", "url": "lessons/046-the-veil-of-ignorance.html", "deepWords": 2285, "deepMins": 11}, {"id": 47, "title": "Why technology does not automatically create progress", "topic": "Technology, AI & Media Ecology", "summary": "Tools expand what people can do, but outcomes depend on institutions, skills, access, incentives and governance. Adoption is not the same as beneficial use.", "url": "lessons/047-why-technology-does-not-automatically-create-progress.html", "deepWords": 2111, "deepMins": 11}, {"id": 48, "title": "The difference between wealth and income", "topic": "Economics, Markets & Incentives", "summary": "Income is a flow over time; wealth is a stock of assets minus liabilities. A high income does not automatically produce financial security.", "url": "lessons/048-the-difference-between-wealth-and-income.html", "deepWords": 2271, "deepMins": 11}, {"id": 49, "title": "The difference between persuasion and manipulation", "topic": "Technology, AI & Media Ecology", "summary": "Persuasion offers reasons that can be examined. Manipulation often hides relevant information, exploits vulnerabilities or makes refusal unnecessarily difficult.", "url": "lessons/049-the-difference-between-persuasion-and-manipulation.html", "deepWords": 2062, "deepMins": 10}, {"id": 50, "title": "What is a cognitive bias?", "topic": "Decision Science & Cognitive Biases", "summary": "A cognitive bias is a systematic pattern in judgment that can arise from shortcuts, context, motivation or the limits of attention. It is not a diagnosis of foolishness.", "url": "lessons/050-what-is-a-cognitive-bias.html", "deepWords": 2009, "deepMins": 10}, {"id": 51, "title": "The commons of knowledge: why open knowledge matters", "topic": "Technology, AI & Media Ecology", "summary": "Shared knowledge can be reused and improved by many people. Open access can widen participation, but quality, maintenance, attribution and sustainability still need attention.", "url": "lessons/051-the-commons-of-knowledge-why-open-knowledge-matters.html", "deepWords": 2866, "deepMins": 14}, {"id": 52, "title": "The Cognitive Revolution and myth-making", "topic": "Institutions, History & Anthropology", "summary": "The evolutionary breakthrough of Homo sapiens was not superior physical strength, but language capable of transmitting information about things that do not exist.", "url": "lessons/052-the-cognitive-revolution.html", "deepWords": 2773, "deepMins": 14}, {"id": 53, "title": "The importance of maintenance", "topic": "Systems Thinking & Complexity", "summary": "Systems often receive attention when they are launched or broken, while routine maintenance remains invisible. Neglected maintenance creates future cost and fragility.", "url": "lessons/053-the-importance-of-maintenance.html", "deepWords": 2675, "deepMins": 13}, {"id": 54, "title": "Why privacy is a condition for freedom", "topic": "Technology, AI & Media Ecology", "summary": "Privacy gives people room to think, associate and experiment without constant observation. The appropriate balance depends on purpose, power, safeguards and accountability.", "url": "lessons/054-why-privacy-is-a-condition-for-freedom.html", "deepWords": 2749, "deepMins": 14}, {"id": 55, "title": "Yin-Yang: the harmony of dynamic opposites", "topic": "Hindu Philosophy & Classical Strategy", "summary": "Opposites are not warring enemies to be exterminated; they are complementary, interdependent phases of a single, continuous, oscillating system.", "url": "lessons/055-yin-yang-and-dynamic-polarity.html", "deepWords": 2193, "deepMins": 11}, {"id": 56, "title": "Why experts can be wrong", "topic": "Scientific Reasoning & Epistemology", "summary": "Expertise improves performance in domains with valid feedback and learnable patterns, but confidence can exceed evidence in uncertain or poorly calibrated environments.", "url": "lessons/056-why-experts-can-be-wrong.html", "deepWords": 2332, "deepMins": 12}, {"id": 57, "title": "The alignment problem: whose goals are being optimised?", "topic": "Technology, AI & Media Ecology", "summary": "A system can satisfy a measurable objective while failing the broader human purpose behind it. Alignment requires attention to values, incentives, context and unintended effects.", "url": "lessons/057-the-alignment-problem-whose-goals-are-being-optimised.html", "deepWords": 2822, "deepMins": 14}, {"id": 58, "title": "Why saying no can protect good work", "topic": "Systems Thinking & Complexity", "summary": "Every commitment uses time, attention and credibility. Saying yes without capacity can reduce the quality of existing obligations and create avoidable disappointment.", "url": "lessons/058-why-saying-no-can-protect-good-work.html", "deepWords": 1999, "deepMins": 10}, {"id": 59, "title": "Why intellectual humility improves judgment", "topic": "Scientific Reasoning & Epistemology", "summary": "Intellectual humility means recognising the limits of one&#39;s knowledge and remaining open to correction. It is compatible with firm conclusions when evidence is strong.", "url": "lessons/059-why-intellectual-humility-improves-judgment.html", "deepWords": 2389, "deepMins": 12}, {"id": 60, "title": "Trade creates gains—and difficult adjustments", "topic": "Economics, Markets & Incentives", "summary": "Trade can increase total welfare through specialisation and exchange, while distributing gains and losses unevenly across workers, firms and regions.", "url": "lessons/060-trade-creates-gains-and-difficult-adjustments.html", "deepWords": 2305, "deepMins": 12}, {"id": 61, "title": "Why cities create opportunity—and inequality", "topic": "Institutions, History & Anthropology", "summary": "Cities concentrate people, skills, services and ideas, enabling exchange and innovation. They also concentrate congestion, pollution, exclusion and unequal access to opportunity.", "url": "lessons/061-why-cities-create-opportunity-and-inequality.html", "deepWords": 2755, "deepMins": 14}, {"id": 62, "title": "The tragedy of the commons—and its alternatives", "topic": "Game Theory & Cooperation", "summary": "Shared resources can be depleted when users face incentives to take more while costs are distributed. But collapse is not inevitable: communities can create workable governance rules.", "url": "lessons/062-the-tragedy-of-the-commons-and-its-alternatives.html", "deepWords": 2016, "deepMins": 10}, {"id": 63, "title": "Why people follow authority", "topic": "Social Psychology & Human Nature", "summary": "Authority can coordinate action and transmit expertise, but status cues can also discourage scrutiny. A title is evidence of a role, not proof that every claim is correct.", "url": "lessons/063-why-people-follow-authority.html", "deepWords": 2118, "deepMins": 11}, {"id": 64, "title": "Why geography influences history", "topic": "Institutions, History & Anthropology", "summary": "Climate, terrain, rivers, disease environments and access to trade routes shape opportunities and constraints. They influence history without determining it completely.", "url": "lessons/064-why-geography-influences-history.html", "deepWords": 2270, "deepMins": 11}, {"id": 65, "title": "What is justice?", "topic": "Philosophy, Ethics & Mind", "summary": "Justice concerns how benefits, burdens, rights, opportunities and recognition should be distributed. Different theories prioritise equality, liberty, need, desert or capability.", "url": "lessons/065-what-is-justice.html", "deepWords": 2319, "deepMins": 12}, {"id": 66, "title": "Cultural humility: learning without stereotyping", "topic": "Institutions, History & Anthropology", "summary": "Cultural humility recognises that no individual represents an entire culture and that understanding requires listening, context and willingness to revise assumptions.", "url": "lessons/066-cultural-humility-learning-without-stereotyping.html", "deepWords": 3018, "deepMins": 15}, {"id": 67, "title": "Scepticism: how much can we really know?", "topic": "Philosophy, Ethics & Mind", "summary": "Philosophical scepticism tests the grounds of belief. It can expose unjustified certainty, but radical doubt can also make ordinary action impossible.", "url": "lessons/067-scepticism-how-much-can-we-really-know.html", "deepWords": 2106, "deepMins": 11}, {"id": 68, "title": "Systems thinking: look for feedback loops", "topic": "Systems Thinking & Complexity", "summary": "Systems contain interacting elements, feedback loops, delays and unintended consequences. Local fixes can create problems elsewhere when relationships are ignored.", "url": "lessons/068-systems-thinking-look-for-feedback-loops.html", "deepWords": 2476, "deepMins": 12}, {"id": 69, "title": "The Prisoner’s Dilemma in everyday life", "topic": "Game Theory & Cooperation", "summary": "People can make individually sensible, self-protecting choices that leave everyone worse off. The structure of incentives often matters far more than anyone's stated intentions.", "url": "lessons/069-the-prisoner-s-dilemma-in-everyday-life.html", "deepWords": 2521, "deepMins": 13}, {"id": 70, "title": "The value of boredom and unstructured time", "topic": "Social Psychology & Human Nature", "summary": "Unstructured time can allow reflection, mind-wandering and creative association. Constant stimulation may reduce opportunities to notice questions that have not yet become tasks.", "url": "lessons/070-the-value-of-boredom-and-unstructured-time.html", "deepWords": 2436, "deepMins": 12}, {"id": 71, "title": "Existentialism and responsibility", "topic": "Philosophy, Ethics & Mind", "summary": "Existentialist thinkers explore freedom, choice, meaning and responsibility in a world that may not provide ready-made answers. Freedom can be unsettling because choices have consequences.", "url": "lessons/071-existentialism-and-responsibility.html", "deepWords": 2151, "deepMins": 11}, {"id": 72, "title": "How stories shape what societies remember", "topic": "Institutions, History & Anthropology", "summary": "Collective memory is shaped by institutions, rituals, education, media and the stories communities repeat. Memory can preserve identity while simplifying the past.", "url": "lessons/072-how-stories-shape-what-societies-remember.html", "deepWords": 2066, "deepMins": 10}, {"id": 73, "title": "How propaganda simplifies the world", "topic": "Technology, AI & Media Ecology", "summary": "Propaganda often uses repetition, emotional cues, selective facts and in-group/out-group narratives. Its influence depends on context, trust and distribution, not merely on false statements.", "url": "lessons/073-how-propaganda-simplifies-the-world.html", "deepWords": 2084, "deepMins": 10}, {"id": 74, "title": "Socrates and the examined life", "topic": "Philosophy, Ethics & Mind", "summary": "Socratic questioning tests definitions, assumptions and contradictions. The goal is not to win an argument but to discover whether a belief survives careful examination.", "url": "lessons/074-socrates-and-the-examined-life.html", "deepWords": 2127, "deepMins": 11}, {"id": 75, "title": "The three universal unifiers of humankind", "topic": "Institutions, History & Anthropology", "summary": "Global cooperation across cultural divides was forged through three practical institutions: the monetary order, the imperial order, and universal religions.", "url": "lessons/075-the-unification-of-humankind.html", "deepWords": 2487, "deepMins": 12}, {"id": 76, "title": "How to negotiate without treating everything as a contest", "topic": "Game Theory & Cooperation", "summary": "Good negotiation explores interests, alternatives and trade-offs. Positions are what people demand; interests are the reasons those demands matter.", "url": "lessons/076-how-to-negotiate-without-treating-everything-as-a-contest.html", "deepWords": 2114, "deepMins": 11}, {"id": 77, "title": "Maya: piercing the veil of sensory conditioning", "topic": "Hindu Philosophy & Classical Strategy", "summary": "The world as perceived through uncalibrated senses is a projection of conditioning. Mistaking the transient surface for permanent truth is the root of suffering.", "url": "lessons/077-maya-and-the-architecture-of-illusion.html", "deepWords": 2267, "deepMins": 11}, {"id": 78, "title": "Risk is not the same as uncertainty", "topic": "Decision Science & Cognitive Biases", "summary": "Risk can often be described with probabilities based on data or a defensible model. Uncertainty includes situations where probabilities or outcomes are poorly known.", "url": "lessons/078-risk-is-not-the-same-as-uncertainty.html", "deepWords": 2327, "deepMins": 12}, {"id": 79, "title": "Why measurement changes behaviour", "topic": "Systems Thinking & Complexity", "summary": "When a measure becomes a target, people may optimise the number rather than the underlying goal. Metrics are useful signals, but they can distort behaviour when treated as the whole truth.", "url": "lessons/079-why-measurement-changes-behaviour.html", "deepWords": 1975, "deepMins": 10}, {"id": 80, "title": "Why loneliness is not the same as solitude", "topic": "Social Psychology & Human Nature", "summary": "Solitude is time alone that can be chosen and restorative. Loneliness is the distress of feeling insufficiently connected, which can occur even in a crowd.", "url": "lessons/080-why-loneliness-is-not-the-same-as-solitude.html", "deepWords": 1999, "deepMins": 10}, {"id": 81, "title": "Free will, choice and responsibility", "topic": "Philosophy, Ethics & Mind", "summary": "Debates about free will ask whether human choices are compatible with causal determination and what responsibility requires. Different positions define freedom and causation differently.", "url": "lessons/081-free-will-choice-and-responsibility.html", "deepWords": 2114, "deepMins": 11}, {"id": 82, "title": "Boundaries are not hostility", "topic": "Social Psychology & Human Nature", "summary": "Boundaries clarify what you can accept, provide or participate in. They are most useful when communicated clearly and enforced consistently rather than used as threats.", "url": "lessons/082-boundaries-are-not-hostility.html", "deepWords": 2603, "deepMins": 13}, {"id": 83, "title": "Why organisations resist change", "topic": "Systems Thinking & Complexity", "summary": "Resistance may reflect habit, identity, uncertainty, lost status, workload or rational concern about a poorly designed change. It is not always stubbornness.", "url": "lessons/083-why-organisations-resist-change.html", "deepWords": 1968, "deepMins": 10}, {"id": 84, "title": "Why trust is built through small actions", "topic": "Social Psychology & Human Nature", "summary": "Trust usually grows through repeated, observable behaviour: keeping promises, being candid about limits and acting consistently when there is little immediate reward.", "url": "lessons/084-why-trust-is-built-through-small-actions.html", "deepWords": 1945, "deepMins": 10}, {"id": 85, "title": "The sunk-cost trap", "topic": "Decision Science & Cognitive Biases", "summary": "Past expenditure cannot be recovered by continuing. The relevant question is whether the next unit of time, money or effort is worth investing.", "url": "lessons/085-the-sunk-cost-trap.html", "deepWords": 2131, "deepMins": 11}, {"id": 86, "title": "The fundamental attribution error", "topic": "Social Psychology & Human Nature", "summary": "We can over-explain other people&#39;s behaviour through character while underestimating the situation they are in. Our own behaviour often receives more contextual explanation.", "url": "lessons/086-the-fundamental-attribution-error.html", "deepWords": 2170, "deepMins": 11}, {"id": 87, "title": "Open-source software as organised cooperation", "topic": "Game Theory & Cooperation", "summary": "Open-source projects show how contributors can cooperate without a single employer directing every action. Governance, reputation, modular work and shared standards help sustain collaboration.", "url": "lessons/087-open-source-software-as-organised-cooperation.html", "deepWords": 2467, "deepMins": 12}, {"id": 88, "title": "How to disagree without making an enemy", "topic": "Social Psychology & Human Nature", "summary": "Productive disagreement focuses on claims, evidence and consequences while preserving the other person&#39;s dignity. It requires listening and clear boundaries.", "url": "lessons/088-how-to-disagree-without-making-an-enemy.html", "deepWords": 2496, "deepMins": 12}, {"id": 89, "title": "The halo effect", "topic": "Decision Science & Cognitive Biases", "summary": "A positive impression in one area can spill over into judgments about unrelated qualities. Confidence, charm or prestige can be mistaken for competence.", "url": "lessons/089-the-halo-effect.html", "deepWords": 2025, "deepMins": 10}, {"id": 90, "title": "Wu Wei: action aligned with the grain of nature", "topic": "Hindu Philosophy & Classical Strategy", "summary": "Wu Wei is not passive laziness or fatalistic inaction; it is effortless action aligned with the natural contours and momentum of reality.", "url": "lessons/090-wu-wei-effortless-action.html", "deepWords": 2276, "deepMins": 11}, {"id": 91, "title": "Productivity is more than working harder", "topic": "Economics, Markets & Incentives", "summary": "Productivity concerns output relative to inputs. It can improve through skills, tools, technology, better processes and coordination—not simply longer hours.", "url": "lessons/091-productivity-is-more-than-working-harder.html", "deepWords": 2225, "deepMins": 11}, {"id": 92, "title": "BATNA: know your alternative", "topic": "Game Theory & Cooperation", "summary": "Your best alternative to a negotiated agreement is the option available if no deal is reached. A stronger alternative usually improves your ability to negotiate without bluffing.", "url": "lessons/092-batna-know-your-alternative.html", "deepWords": 2039, "deepMins": 10}, {"id": 93, "title": "Ren and Li: internal character shaped by sacred form", "topic": "Hindu Philosophy & Classical Strategy", "summary": "Benevolent empathy (Ren) cannot flourish without the social architecture of ritual propriety (Li). Outward form cultivates inner virtue.", "url": "lessons/093-ren-and-li-benevolence-and-ritual-propriety.html", "deepWords": 2247, "deepMins": 11}, {"id": 94, "title": "Why groups sometimes become less thoughtful", "topic": "Social Psychology & Human Nature", "summary": "Groups can improve judgment by pooling knowledge, but conformity, status and fear of dissent can suppress useful disagreement.", "url": "lessons/094-why-groups-sometimes-become-less-thoughtful.html", "deepWords": 2351, "deepMins": 12}, {"id": 95, "title": "Vishada: existential dejection as the threshold of wisdom", "topic": "Hindu Philosophy & Classical Strategy", "summary": "The collapse of easy certainty and the onset of profound moral hesitation is not failure; it is the essential prerequisite for genuine philosophical transformation.", "url": "lessons/095-vishada-as-the-gateway-to-clarity.html", "deepWords": 2417, "deepMins": 12}, {"id": 96, "title": "Why humour can reveal truth", "topic": "Social Psychology & Human Nature", "summary": "Humour can expose contradictions, challenge authority and create belonging. It can also exclude or humiliate, depending on who controls the joke and who bears its cost.", "url": "lessons/096-why-humour-can-reveal-truth.html", "deepWords": 2053, "deepMins": 10}, {"id": 97, "title": "Winning without fighting: the supreme art of strategy", "topic": "Game Theory & Cooperation", "summary": "To fight and conquer in a hundred battles is not supreme excellence; supreme excellence consists in breaking the enemy's resistance without fighting.", "url": "lessons/097-winning-without-fighting-supreme-strategy.html", "deepWords": 2295, "deepMins": 11}, {"id": 98, "title": "What money actually does", "topic": "Economics, Markets & Incentives", "summary": "Money functions as a medium of exchange, a unit of account and a store of value. Its usefulness depends on shared confidence and institutions that support it.", "url": "lessons/098-what-money-actually-does.html", "deepWords": 2399, "deepMins": 12}, {"id": 99, "title": "Why intelligent people make poor decisions", "topic": "Decision Science & Cognitive Biases", "summary": "High IQ is an engine of processing speed and pattern recognition, not epistemic humility. When smart people err, they construct more formidable rationalizations for their mistakes.", "url": "lessons/099-why-intelligent-people-make-poor-decisions.html", "deepWords": 2951, "deepMins": 15}, {"id": 100, "title": "Dataism and the shift from human feelings to algorithms", "topic": "Technology, AI & Media Ecology", "summary": "When human beings are understood as biochemical data-processing systems, authority shifts from inner intuition to external predictive algorithms.", "url": "lessons/100-dataism-and-the-algorithmic-self.html", "deepWords": 2438, "deepMins": 12}, {"id": 101, "title": "Public goods and the free-rider problem", "topic": "Game Theory & Cooperation", "summary": "Some benefits are difficult to restrict to paying users, so individuals may prefer others to bear the cost. This creates challenges for funding and maintaining shared resources.", "url": "lessons/101-public-goods-and-the-free-rider-problem.html", "deepWords": 2092, "deepMins": 10}, {"id": 102, "title": "The ethics of attention", "topic": "Technology, AI & Media Ecology", "summary": "Attention is limited, and many digital systems compete to capture it. Design choices can support learning and connection or encourage compulsive use.", "url": "lessons/102-the-ethics-of-attention.html", "deepWords": 2940, "deepMins": 15}, {"id": 103, "title": "Sthitaprajna: cultivating the unshakeable mind", "topic": "Hindu Philosophy & Classical Strategy", "summary": "The steady mind neither rejoices in prosperity nor collapses in adversity. Emotional equilibrium is the bedrock of wise judgment.", "url": "lessons/103-sthitaprajna-the-steady-mind.html", "deepWords": 2330, "deepMins": 12}, {"id": 104, "title": "The precautionary principle and unintended consequences", "topic": "Systems Thinking & Complexity", "summary": "When potential harm is serious and evidence incomplete, precaution may be justified. But excessive precaution can also block beneficial action; proportionality matters.", "url": "lessons/104-the-precautionary-principle-and-unintended-consequences.html", "deepWords": 2087, "deepMins": 10}, {"id": 105, "title": "Nishkama Karma: action detached from outcome", "topic": "Hindu Philosophy & Classical Strategy", "summary": "You have a right to your labor, but never to the fruits of your labor. Pour complete excellence into action while surrendering anxiety over results.", "url": "lessons/105-nishkama-karma-detached-action.html", "deepWords": 2456, "deepMins": 12}, {"id": 106, "title": "Loss aversion and the fear of giving something up", "topic": "Decision Science & Cognitive Biases", "summary": "Losses often feel more consequential than equivalent gains. This can make people cling to the familiar or reject worthwhile change.", "url": "lessons/106-loss-aversion-and-the-fear-of-giving-something-up.html", "deepWords": 2100, "deepMins": 10}, {"id": 107, "title": "Reciprocity: the social force of giving", "topic": "Social Psychology & Human Nature", "summary": "People often feel pressure to return favours. Reciprocity supports cooperation, but it can also be used to create obligation or manipulate decisions.", "url": "lessons/107-reciprocity-the-social-force-of-giving.html", "deepWords": 2093, "deepMins": 10}, {"id": 108, "title": "Shi, Shu, and Fa: the legalist engine of enduring institutions", "topic": "Institutions, History & Anthropology", "summary": "Enduring governance cannot rely on the virtuous whims of saintly rulers. Systems survive through objective law (Fa), administrative audits (Shu), and structural leverage (Shi).", "url": "lessons/108-shi-shu-fa-the-mechanics-of-institutional-power.html", "deepWords": 2378, "deepMins": 12}, {"id": 109, "title": "How to become someone people trust with difficult problems", "topic": "Social Psychology & Human Nature", "summary": "People rely on those who clarify ambiguity, communicate constraints, follow through and surface risks early. Expertise matters, but reliability makes it usable.", "url": "lessons/109-how-to-become-someone-people-trust-with-difficult-problems.html", "deepWords": 1979, "deepMins": 10}, {"id": 110, "title": "The difference between being busy and being useful", "topic": "Systems Thinking & Complexity", "summary": "Activity is not the same as contribution. Useful work changes an outcome that matters to someone, and its value should be assessed from the recipient&#39;s perspective.", "url": "lessons/110-the-difference-between-being-busy-and-being-useful.html", "deepWords": 2118, "deepMins": 11}, {"id": 111, "title": "The many meanings of consciousness", "topic": "Philosophy, Ethics & Mind", "summary": "Consciousness can refer to wakefulness, subjective experience, access to information or self-awareness. These are related but not identical questions.", "url": "lessons/111-the-many-meanings-of-consciousness.html", "deepWords": 2043, "deepMins": 10}, {"id": 112, "title": "Advaita: the distinction between self and roles", "topic": "Hindu Philosophy & Classical Strategy", "summary": "Advaita Vedanta investigates the relationship between the individual self, awareness and ultimate reality. Its claims are philosophical and contemplative, not interchangeable with findings from neuroscience.", "url": "lessons/112-advaita-the-distinction-between-self-and-roles.html", "deepWords": 2173, "deepMins": 11}, {"id": 113, "title": "What makes evidence strong?", "topic": "Scientific Reasoning & Epistemology", "summary": "Evidence quality depends on relevance, measurement, comparison, sample selection, uncertainty and the possibility of alternative explanations.", "url": "lessons/113-what-makes-evidence-strong.html", "deepWords": 2191, "deepMins": 11}, {"id": 114, "title": "How incentives shape behaviour", "topic": "Economics, Markets & Incentives", "summary": "People respond not only to values and instructions but also to rewards, penalties, status and the costs of choosing differently.", "url": "lessons/114-how-incentives-shape-behaviour.html", "deepWords": 2359, "deepMins": 12}, {"id": 115, "title": "The Three Gunas: the ecology of human motivation", "topic": "Hindu Philosophy & Classical Strategy", "summary": "All nature and human consciousness operate through three fundamental forces: clarity and harmony (sattva), passion and agitation (rajas), and inertia and darkness (tamas).", "url": "lessons/115-the-three-gunas-sattva-rajas-tamas.html", "deepWords": 2232, "deepMins": 11}, {"id": 116, "title": "The danger of human irrelevance in the automated age", "topic": "Technology, AI & Media Ecology", "summary": "The 20th century was a struggle against exploitation; the 21st-century danger is obsolescence. Being economically irrelevant is far more perilous than being exploited.", "url": "lessons/116-the-problem-of-irrelevant-humans.html", "deepWords": 2355, "deepMins": 12}, {"id": 117, "title": "Survivorship bias: learning only from winners", "topic": "Decision Science & Cognitive Biases", "summary": "Studying only visible successes hides the failures that disappeared from view. This can make a strategy look more reliable than it is.", "url": "lessons/117-survivorship-bias-learning-only-from-winners.html", "deepWords": 2120, "deepMins": 11}, {"id": 118, "title": "Formlessness: the strategic power of water", "topic": "Hindu Philosophy & Classical Strategy", "summary": "Water has no constant shape, yet it carves through granite mountains. The highest strategic adaptability is to be formless, matching the contour of the moment.", "url": "lessons/118-formlessness-and-adaptability.html", "deepWords": 2267, "deepMins": 11}, {"id": 119, "title": "Path dependence: why history keeps shaping the present", "topic": "Systems Thinking & Complexity", "summary": "Earlier choices can shape later options through infrastructure, habits, standards and institutions. A system may persist even when alternatives appear better.", "url": "lessons/119-path-dependence-why-history-keeps-shaping-the-present.html", "deepWords": 2320, "deepMins": 12}, {"id": 120, "title": "The difference between kindness and people-pleasing", "topic": "Social Psychology & Human Nature", "summary": "Kindness considers another person&#39;s welfare while retaining honesty and self-respect. People-pleasing may prioritise approval at the expense of truth or sustainable commitments.", "url": "lessons/120-the-difference-between-kindness-and-people-pleasing.html", "deepWords": 2433, "deepMins": 12}, {"id": 121, "title": "Confirmation bias: the comfort of being right", "topic": "Decision Science & Cognitive Biases", "summary": "People tend to notice, seek or interpret evidence in ways that support existing beliefs. The effect can operate even when people value accuracy.", "url": "lessons/121-confirmation-bias-the-comfort-of-being-right.html", "deepWords": 2027, "deepMins": 10}, {"id": 122, "title": "The difference between efficiency and effectiveness", "topic": "Systems Thinking & Complexity", "summary": "Efficiency concerns the resources used relative to output. Effectiveness concerns whether the right outcome is achieved. A process can be efficient at doing the wrong thing.", "url": "lessons/122-the-difference-between-efficiency-and-effectiveness.html", "deepWords": 2067, "deepMins": 10}, {"id": 123, "title": "Why first impressions can mislead", "topic": "Decision Science & Cognitive Biases", "summary": "Early information can anchor later interpretation. First impressions are useful hypotheses, not reliable verdicts.", "url": "lessons/123-why-first-impressions-can-mislead.html", "deepWords": 2042, "deepMins": 10}];

const grid = document.querySelector("#lesson-grid"),
      search = document.querySelector("#search"),
      chips = document.querySelector("#topic-chips"),
      count = document.querySelector("#result-count"),
      empty = document.querySelector("#empty"),
      tileButton = document.querySelector("#tiles-button"),
      listButton = document.querySelector("#list-button"),
      shuffleButton = document.querySelector("#shuffle-button"),
      sortButton = document.querySelector("#sort-button"),
      randomButton = document.querySelector("#random-button");

let activeTopic = "All", view = "tiles", isShuffled = false;
let displayedLessons = [...lessons];

const CATEGORY_ORDER = [
  "All",
  "Decision Science & Cognitive Biases",
  "Social Psychology & Human Nature",
  "Game Theory & Cooperation",
  "Economics, Markets & Incentives",
  "Systems Thinking & Complexity",
  "Scientific Reasoning & Epistemology",
  "Philosophy, Ethics & Mind",
  "Hindu Philosophy & Classical Strategy",
  "Institutions, History & Anthropology",
  "Technology, AI & Media Ecology"
];

// Calculate counts per topic
const topicCounts = {};
lessons.forEach(l => {
  topicCounts[l.topic] = (topicCounts[l.topic] || 0) + 1;
});

function getDomain(topic) {
  const t = topic.toLowerCase();
  if (t.includes('decision') || t.includes('psychology')) return 'mind';
  if (t.includes('game') || t.includes('economics') || t.includes('systems')) return 'systems';
  if (t.includes('hindu') || t.includes('philosophy')) return 'philosophy';
  if (t.includes('institutions') || t.includes('history')) return 'society';
  if (t.includes('scientific') || t.includes('technology')) return 'science';
  return 'mind';
}

// Generate topic chips with live counts and domain styling
if (chips) {
  CATEGORY_ORDER.forEach(topic => {
    const countVal = topic === "All" ? lessons.length : (topicCounts[topic] || 0);
    const domain = topic === "All" ? "all" : getDomain(topic);
    
    const b = document.createElement("button");
    b.type = "button";
    b.className = `topic-chip chip-${domain}`;
    b.setAttribute("aria-pressed", String(topic === "All"));
    b.setAttribute("data-topic", topic);
    b.innerHTML = `<span class="chip-name">${topic}</span><span class="chip-count">${countVal}</span>`;
    b.addEventListener("click", () => setTopic(topic));
    chips.append(b);
  });
}

function setTopic(t) {
  activeTopic = t;
  if (chips) {
    [...chips.children].forEach(b => {
      b.setAttribute("aria-pressed", String(b.getAttribute("data-topic") === t));
    });
  }
  render();
}

function setView(v) {
  view = v;
  if (tileButton) tileButton.setAttribute("aria-pressed", String(v === "tiles"));
  if (listButton) listButton.setAttribute("aria-pressed", String(v === "list"));
  render();
}

function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function doShuffle() {
  isShuffled = true;
  displayedLessons = shuffleArray(lessons);
  if (shuffleButton) shuffleButton.setAttribute("aria-pressed", "true");
  if (sortButton) sortButton.setAttribute("aria-pressed", "false");
  render();
}

function doSort() {
  isShuffled = false;
  displayedLessons = [...lessons].sort((a, b) => a.id - b.id);
  if (shuffleButton) shuffleButton.setAttribute("aria-pressed", "false");
  if (sortButton) sortButton.setAttribute("aria-pressed", "true");
  render();
}

function render() {
  const q = search ? search.value.trim().toLowerCase() : "";
  const source = isShuffled ? displayedLessons : lessons;
  const found = source.filter(x => 
    (activeTopic === "All" || x.topic === activeTopic) && 
    `${x.title} ${x.topic} ${x.summary}`.toLowerCase().includes(q)
  );
  
  grid.className = view === "list" ? "tile-grid list-view" : "tile-grid";
  grid.replaceChildren();
  
  found.forEach((x, index) => {
    const domain = getDomain(x.topic);
    const card = document.createElement("article");
    card.className = `lesson-card domain-${domain}`;
    card.style.animationDelay = `${Math.min(index * 12, 240)}ms`;
    
    // Header Meta: ID and Domain Tag
    const meta = document.createElement("div");
    meta.className = "card-meta";
    
    const n = document.createElement("span");
    n.className = "card-number";
    n.textContent = String(x.id).padStart(3, "0");
    
    const t = document.createElement("span");
    t.className = `card-topic-tag tag-${domain}`;
    t.textContent = x.topic;
    
    meta.append(n, t);
    
    // Title
    const h = document.createElement("h2");
    const a = document.createElement("a");
    a.href = x.url;
    a.textContent = x.title;
    h.append(a);
    
    // Summary
    const p = document.createElement("p");
    p.className = "card-summary";
    p.textContent = x.summary;
    
    // Reading metadata whisper
    const metaBottom = document.createElement("div");
    metaBottom.className = "card-footer-meta";
    metaBottom.innerHTML = `<span class="words-pill">${(x.deepWords || 2200).toLocaleString()} words</span><span class="dot">·</span><span>Primary Sources</span>`;
    
    // Dual Action Buttons
    const actions = document.createElement("div");
    actions.className = "card-actions";
    
    const btnNote = document.createElement("a");
    btnNote.className = "btn-field-note";
    btnNote.href = x.url;
    btnNote.innerHTML = '<span class="btn-icon">⚡</span> <span>2-min Note</span>';
    
    const btnDeep = document.createElement("a");
    btnDeep.className = "btn-deep-dive";
    btnDeep.href = x.url.replace("lessons/", "deep-dives/");
    btnDeep.innerHTML = `<span>📖 ${x.deepMins}-min Read</span> <span class="btn-arrow" aria-hidden="true">→</span>`;
    
    actions.append(btnNote, btnDeep);
    card.append(meta, h, p, metaBottom, actions);
    grid.append(card);
  });
  
  if (count) {
    count.innerHTML = `Showing <strong>${found.length}</strong> of ${lessons.length} lenses${isShuffled ? ' <span class="shuffled-badge">🔀 Rearranged</span>' : ''}`;
  }
  if (empty) {
    empty.style.display = found.length ? "none" : "block";
  }
}

if (search) {
  search.addEventListener("input", render);
}

// Keyboard shortcuts: '/' to search, 'Escape' to clear
document.addEventListener("keydown", (e) => {
  if (e.key === "/" && document.activeElement !== search && search) {
    e.preventDefault();
    search.focus();
    search.select();
  } else if (e.key === "Escape" && document.activeElement === search && search) {
    search.value = "";
    render();
    search.blur();
  }
});

if (tileButton) tileButton.addEventListener("click", () => setView("tiles"));
if (listButton) listButton.addEventListener("click", () => setView("list"));
if (shuffleButton) shuffleButton.addEventListener("click", doShuffle);
if (sortButton) sortButton.addEventListener("click", doSort);

if (randomButton) {
  randomButton.addEventListener("click", () => {
    const q = search ? search.value.trim().toLowerCase() : "";
    const available = lessons.filter(x => (activeTopic === "All" || x.topic === activeTopic) && `${x.title} ${x.topic} ${x.summary}`.toLowerCase().includes(q));
    const pool = available.length ? available : lessons;
    const pick = pool[Math.floor(Math.random() * pool.length)];
    window.location.href = pick.url;
  });
}

render();
